class Bucket:
    def __init__(self, rate, capacity, now=0):
        self.rate, self.capacity = rate, capacity
        self.tokens, self.last = capacity, now
    def allow(self, now):
        if now < self.last: raise ValueError("clock moved backwards")
        self.tokens = min(self.capacity, self.tokens+(now-self.last)*self.rate)
        self.last = now
        if self.tokens < 1: return False
        self.tokens -= 1; return True

def crawl(start, links):
    from urllib.parse import urlparse
    host = urlparse(start).hostname; seen = set(); todo = [start]
    while todo:
        url = todo.pop()
        if url in seen or urlparse(url).hostname != host: continue
        seen.add(url); todo.extend(links.get(url, []))
    return sorted(seen)

