import numpy as np
def step(x, y, w, b, lr=0.1, l2=0.0):
    z = x@w+b
    p = np.exp(-np.logaddexp(0, -z))
    error = p-y
    return w-lr*(x.T@error/len(y)+l2*w), b-lr*error.mean()
